          state.projects = [ch.projectA, ch.pivotProject, ch.projectC];
          state.match = 'any';
          selectIngredient(ch.lemmaAB.id, ch.projectA, ch.pivotProject, [ch.lemmaAB.id, ch.lemmaBC.id]);
          renderApp();
