function syncSignalPills() {
  document.querySelectorAll('[data-signal-tier]').forEach(btn => {
    btn.setAttribute('aria-pressed', String(btn.dataset.signalTier === state.signalTier));
  });
}

function triggerSurpriseBridge() {
  const mechs = semanticMechanisms?.highLevelMechanisms || unrelatedBridges?.highLevelMechanisms || [];
  const isos = semanticMechanisms?.customIsomorphisms || unrelatedBridges?.customIsomorphisms || [];
  state.lens = 'serendipity';
  if (mechs.length && Math.random() < 0.55) {
    state.serenSubmode = 'mechanisms';
    state.selectedMechanismId = mechs[Math.floor(Math.random() * mechs.length)].id;
    state.serenQuery = '';
    syncUrl(false);
    renderApp();
    return;
  }
  if (isos.length) {
    state.serenSubmode = 'isomorphisms';
    state.selectedIsoId = isos[Math.floor(Math.random() * Math.min(60, isos.length))].id;
    state.serenQuery = '';
    syncUrl(false);
    renderApp();
    return;
  }
  if (!unrelatedBridges?.discoveries?.length) return;
  if (Math.random() < 0.5 && unrelatedBridges.twoHopPivotChains?.length) {
    state.serenSubmode = 'chains';
    const pool = unrelatedBridges.twoHopPivotChains;
    state.selectedChainId = pool[Math.floor(Math.random() * Math.min(40, pool.length))].id;
  } else {
    state.serenSubmode = 'motifs';
    const pool = unrelatedBridges.discoveries;
    state.selectedMotifId = pool[Math.floor(Math.random() * Math.min(40, pool.length))].id;
  }
  state.serenQuery = '';
  syncUrl(false);
  renderApp();
}

function renderApp() {
  document.querySelectorAll('.lens-btn').forEach(btn => {
    btn.setAttribute('aria-pressed', String(btn.dataset.lens === state.lens));
  });
  syncSignalPills();

  const mount = $('app-mount');
  if (state.lens === 'galaxy') renderGalaxyLens(mount);
  else if (state.lens === 'serendipity') renderSerendipityLens(mount);
  else if (state.lens === 'paths') renderPathsLens(mount);
  else if (state.lens === 'bridges') renderBridgesLens(mount);
  else if (state.lens === 'constellation') renderConstellationLens(mount);
  else if (state.lens === 'intuition') renderIntuitionLens(mount);
}

async function init() {
  try {
    let m, idx, bm, ip, ub, cc, sm;
    if (window.__CG_PRELOADED__) {
      ({ manifest: m, indexData: idx, bridgeMatrix: bm, insightPaths: ip, unrelatedBridges: ub, constellationCatalog: cc, semanticMechanisms: sm } = window.__CG_PRELOADED__);
    } else {
      [m, idx, bm, ip, ub, cc, sm] = await Promise.all([
        fetchJson(sourceManifest.path),
        fetchJson('data/source-ingredients/index.json'),
        fetchJson('data/discovery/bridge-matrix.json'),
        fetchJson('data/discovery/insight-paths.json'),
        fetchJson('data/discovery/unrelated-bridges.json'),
        fetchJson('data/discovery/constellation-catalog.json'),
        fetchJson('data/discovery/semantic-mechanisms.json').catch(() => null),
      ]);
    }
    manifest = m;
    indexData = idx;
    bridgeMatrix = bm;
    insightPaths = ip;
    unrelatedBridges = ub;
    constellationCatalog = cc;
    semanticMechanisms = sm;
    recordById = new Map(indexData.records.map(r => [r.id, r]));
    state.projects = [...manifest.projectOrder];

    readUrlState();

    document.querySelectorAll('.lens-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        state.lens = btn.dataset.lens;
        syncUrl(false);
        renderApp();
      });
    });

    document.querySelectorAll('[data-signal-tier]').forEach(btn => {
      btn.addEventListener('click', () => {
        const tier = btn.dataset.signalTier;
        state.signalTier = tier;
        state.catSubFilter = tier === 'isomorphisms' ? 'isomorphismsOnly' : 'all';
        state.bridgeMatrixMode = tier;
        if (state.lens === 'serendipity') {
          if (tier === 'mechanisms') state.serenSubmode = 'mechanisms';
          else if (tier === 'isomorphisms') state.serenSubmode = 'isomorphisms';
          else if (tier === 'ingredients') state.serenSubmode = 'motifs';
        }
        syncSignalPills();
        syncUrl(false);
        renderApp();
      });
    });

    $('surprise-me-btn')?.addEventListener('click', triggerSurpriseBridge);

    $('brand-home')?.addEventListener('click', ev => {
      ev.preventDefault();
      state.lens = 'galaxy';
      state.ecosystem = 'all';
      state.projects = [...manifest.projectOrder];
      state.match = 'any';
      state.source = null;
      state.activeMotifIds = [];
      syncUrl(false);
      renderApp();
    });

    if (typeof window.addEventListener === 'function') window.addEventListener('keydown', ev => {
      if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) {
        if (ev.key === 'Escape') document.activeElement.blur();
        return;
      }
      if (ev.metaKey || ev.ctrlKey || ev.altKey) return;
      if (ev.key === '/') {
        ev.preventDefault();
        const searchInput = $('gal-q') || $('seren-q') || $('chain-q') || $('path-q') || $('const-q');
        searchInput?.focus();
      } else if (ev.key === 'Escape') {
        if (state.source || state.selectedPath) {
          state.source = null;
          state.activeMotifIds = [];
          state.selectedPath = null;
          syncUrl(false);
          renderApp();
        }
      } else if (ev.key.toLowerCase() === 's') {
        ev.preventDefault();
        triggerSurpriseBridge();
      } else if (['1', '2', '3', '4', '5', '6'].includes(ev.key)) {
        const lenses = ['galaxy', 'serendipity', 'paths', 'bridges', 'constellation', 'intuition'];
        state.lens = lenses[Number(ev.key) - 1];
        syncUrl(false);
        renderApp();
      }
    });

    if (typeof window.addEventListener === 'function') window.addEventListener('popstate', () => {
      readUrlState();
      renderApp();
    });

    renderApp();
  } catch (err) {
    const missingShards = !window.__CG_PRELOADED__;
    $('app-mount').innerHTML = `
      <div style="padding:24px;border:1px solid rgba(223,192,130,0.45);background:#0c1421;border-radius:14px;color:var(--paper);max-width:760px;margin:24px auto">
        <div class="eyebrow" style="color:var(--gold)">CONSTELLATION SHARD DIAGNOSTIC</div>
        <h2 style="margin:6px 0 10px;font-family:var(--font-serif);font-weight:400;font-size:24px">Could Not Initialize Observatory Shards</h2>
        <p style="color:var(--muted);font-size:13.5px;line-height:1.55;margin:0 0 14px">
          ${missingShards
            ? 'The 8 data shards in <code>./chunks/</code> were not found. Rebuild the unified Chrome &amp; Safari shards or start the local server:'
            : 'Could not load constellation data: ' + esc(err && err.message ? err.message : String(err))}
        </p>
        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
          <code style="padding:8px 12px;border-radius:8px;background:#060b13;border:1px solid var(--line-bright);font-size:12px;color:#7dd3fc">python3 -B observatory/scripts/build-cloudflare-dist.py</code>
          <code style="padding:8px 12px;border-radius:8px;background:#060b13;border:1px solid var(--line-bright);font-size:12px;color:#7dd3fc">python3 -B observatory/scripts/serve-observatory.py</code>
        </div>
      </div>`;
  }
}

if (typeof document !== 'undefined' && document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => { init(); });
} else {
  init();
}


