  var leanCode = window.v11GenerateSynthesizedLeanCode();

  var html = '<div class="v11-synthesizer-card" style="padding:18px;border-radius:14px;background:linear-gradient(135deg,rgba(16,185,129,0.12),rgba(15,23,42,0.95));border:1px solid rgba(16,185,129,0.4);margin-bottom:18px;">';
