window.v23RenderConstantOptimizerForMechanism = function(m) {
  var esc = window._v11Esc || function(s){ return String(s || ''); };
  var projs = (m && m.projects && m.projects.length >= 2) ? m.projects : ['carleson', 'erdos-problems', 'FLT'];
  var pA = projs[0] || 'carleson', pB = projs[1] || 'erdos-problems';
  var co = (m && m.constantOptimizer) ? m.constantOptimizer : {
    donorProject: pA,
    targetProject: pB,
    parameterName: 'Step Coercivity Constant γ (' + pA + ' → ' + pB + ')',
    initialComplexity: 240,
    baselineGain: 10,
    donorGain: 32,
    defaultScales: 8,
    baselineExponentText: 'O(N³) [Unpatched ' + pB + ' Baseline]',
    tightenedExponentText: 'O(N log N) [Tightened via ' + pA + ' Donor Constant]',
    leanTheoremRef: 'CommonGround.Verification.BezrukavnikovAffineHeckeLanglandsBridge.constant_tightening_gain',
    formulaSummary: 'residual(γ_donor) = max(0, initialComplexity - K · γ_donor) ≤ initialComplexity - K · γ_baseline'
  };
  var st = window._v23ConstState || { donorBoostPct: 100, activeScales: 8 };
  var K = Number(st.activeScales || co.defaultScales || 8);
  var boostFrac = Number(st.donorBoostPct != null ? st.donorBoostPct : 100) / 100.0;
  var baseG = Number(co.baselineGain || 10);
  var maxDonorG = Number(co.donorGain || 32);
  var effDonorG = Math.round(baseG + (maxDonorG - baseG) * boostFrac);
  var initC = Number(co.initialComplexity || 240);
  var baseResidual = Math.max(0, initC - K * baseG);
  var donorResidual = Math.max(0, initC - K * effDonorG);
  var savings = Math.max(0, baseResidual - donorResidual);
  var baseStepsNeeded = Math.ceil(initC / Math.max(1, baseG));
  var donorStepsNeeded = Math.ceil(initC / Math.max(1, effDonorG));

  var h = '<div class="v23-constant-optimizer-workbench" style="margin-top:14px;padding:14px;border-radius:12px;background:linear-gradient(135deg,rgba(245,158,11,0.12),rgba(15,23,42,0.95));border:1px solid rgba(245,158,11,0.42);">';
  h += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px;">';
  h += '<div><span style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#fbbf24;">Interactive Cross-Project Constant & Exponent Tightening Calculator (V25)</span>';
  h += '<div style="font-size:12px;color:#e2e8f0;margin-top:2px;">Plug <b>' + esc(co.donorProject) + '</b> constant into <b>' + esc(co.targetProject) + '</b> inequality · Verified by <code>' + esc(co.leanTheoremRef) + '</code></div></div>';
  h += '<span style="font-size:10.5px;padding:3px 9px;border-radius:999px;background:rgba(16,185,129,0.2);color:#6ee7b7;border:1px solid rgba(16,185,129,0.4);font-weight:800;">-' + savings + ' Defect Tightening</span>';
  h += '</div>';

  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin-bottom:10px;">';
  h += '<div style="background:rgba(2,6,23,0.75);padding:8px 10px;border-radius:8px;border:1px solid rgba(148,163,184,0.22);">';
  h += '<label style="display:block;font-size:11px;color:#fcd34d;font-weight:700;margin-bottom:4px;">Donor Constant Interpolation (' + Math.round(boostFrac * 100) + '% → γ = ' + effDonorG + '):</label>';
  h += '<input type="range" min="0" max="100" value="' + Math.round(boostFrac * 100) + '" oninput="window._v23ConstState.donorBoostPct=Number(this.value);if(typeof renderInspector===\'function\')renderInspector();if(typeof renderSerendipity===\'function\')renderSerendipity();" style="width:100%;" />';
  h += '</div>';
  h += '<div style="background:rgba(2,6,23,0.75);padding:8px 10px;border-radius:8px;border:1px solid rgba(148,163,184,0.22);">';
  h += '<label style="display:block;font-size:11px;color:#38bdf8;font-weight:700;margin-bottom:4px;">Active Multi-Scale Depth K = ' + K + ' scales:</label>';
  h += '<input type="range" min="1" max="16" value="' + K + '" oninput="window._v23ConstState.activeScales=Number(this.value);if(typeof renderInspector===\'function\')renderInspector();if(typeof renderSerendipity===\'function\')renderSerendipity();" style="width:100%;" />';
  h += '</div></div>';

  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;">';
  h += '<div style="padding:10px;border-radius:8px;background:rgba(69,10,10,0.34);border:1px solid rgba(244,63,94,0.36);">';
  h += '<div style="font-size:10.5px;font-weight:800;color:#fda4af;margin-bottom:4px;">🔴 UNPATCHED BASELINE (`' + esc(co.targetProject) + '`)</div>';
  h += '<div style="font-size:12px;color:#f8fafc;font-weight:700;">Per-Scale Gain γ_base = ' + baseG + '</div>';
  h += '<div style="font-size:11.5px;color:#fecdd3;margin-top:2px;">Residual Obstruction after ' + K + ' scales: <b>' + baseResidual + '</b> / ' + initC + '</div>';
  h += '<div style="font-size:11px;color:#cbd5e1;margin-top:2px;">Scales needed for zero defect: <b>' + baseStepsNeeded + ' steps</b></div>';
  h += '<div style="font-size:10.5px;color:#fca5a5;margin-top:4px;">Asymptotic Bound: <code>' + esc(co.baselineExponentText) + '</code></div>';
  h += '</div>';

  h += '<div style="padding:10px;border-radius:8px;background:rgba(6,78,59,0.36);border:1px solid rgba(16,185,129,0.42);">';
  h += '<div style="font-size:10.5px;font-weight:800;color:#6ee7b7;margin-bottom:4px;">🟢 DONOR-TIGHTENED BOUND (via `' + esc(co.donorProject) + '`)</div>';
  h += '<div style="font-size:12px;color:#f8fafc;font-weight:700;">Per-Scale Gain γ_donor = ' + effDonorG + ' (' + (effDonorG / Math.max(1, baseG)).toFixed(1) + '× sharper)</div>';
  h += '<div style="font-size:11.5px;color:#d1fae5;margin-top:2px;">Residual Obstruction after ' + K + ' scales: <b>' + donorResidual + '</b> / ' + initC + (donorResidual === 0 ? ' EXHAUSTED!' : '') + '</div>';
  h += '<div style="font-size:11px;color:#cbd5e1;margin-top:2px;">Scales needed for zero defect: <b>' + donorStepsNeeded + ' steps</b> (' + Math.max(0, baseStepsNeeded - donorStepsNeeded) + ' fewer scales)</div>';
  h += '<div style="font-size:10.5px;color:#6ee7b7;margin-top:4px;">Tightened Bound: <code>' + esc(co.tightenedExponentText) + '</code></div>';
  h += '</div></div></div>';
  return h;
};

